import csv,re
rows=list(csv.DictReader(open('expenses.csv')))
seen=set(); recs=[]
for r in rows:
    if r['id'] in seen: continue
    seen.add(r['id']); recs.append(r)
print('dupe ids skipped:',len(rows)-len(recs))
# independent date parse
from datetime import date
mon={m:i+1 for i,m in enumerate('jan feb mar apr may jun jul aug sep oct nov dec'.split())}
def d(s):
    s=s.strip()
    for fmt in ('%Y-%m-%d','%m/%d/%Y','%d %b %Y'):
        try:
            x=__import__('datetime').datetime.strptime(s,fmt); return x.date()
        except ValueError: pass
    raise ValueError(s)
def amt(s):
    s=re.sub(r'[A-Za-z$,\s]','',s); return round(float(s)*100)
sel=[]
for r in recs:
    if r['status'].strip().lower()=='void': continue
    x=d(r['date'])
    if (x.year,x.month)==(2026,10): sel.append((r,x,amt(r['amount'])))
print('oct non-void items:',len(sel),'total:',sum(a for _,_,a in sel))
from collections import defaultdict
c=defaultdict(lambda:[0,0])
for r,x,a in sel:
    c[r['category'].strip().lower()][0]+=1; c[r['category'].strip().lower()][1]+=a
for k,v in c.items(): print(k,v)
print('flags',[(r['id'],a) for r,x,a in sel if a>50000])
